"use client";

import { useState, type CSSProperties } from "react";
import "./section-theme-handoff.css";

export interface SectionThemeChapter {
  id: string;
  title: string;
  summary: string;
  background: string;
  foreground: string;
  accent: string;
}

export interface SectionThemeHandoffProps {
  chapters: SectionThemeChapter[];
  navigationLabel?: string;
  className?: string;
}

export function SectionThemeHandoff({
  chapters,
  navigationLabel = "Story chapters",
  className = "",
}: SectionThemeHandoffProps) {
  const [activeId, setActiveId] = useState(chapters[0]?.id ?? "");
  const active = chapters.find((chapter) => chapter.id === activeId) ?? chapters[0];

  if (!active) return null;

  const theme = {
    "--tb-theme-bg": active.background,
    "--tb-theme-fg": active.foreground,
    "--tb-theme-accent": active.accent,
  } as CSSProperties;

  return (
    <section
      className={`tb-section-theme-handoff ${className}`.trim()}
      style={theme}
    >
      <div className="tb-section-theme-handoff__layout">
        <div
          className="tb-section-theme-handoff__nav"
          role="group"
          aria-label={navigationLabel}
        >
          {chapters.map((chapter, index) => (
            <button
              type="button"
              key={chapter.id}
              aria-pressed={chapter.id === active.id}
              onClick={() => setActiveId(chapter.id)}
            >
              <span aria-hidden="true">{String(index + 1).padStart(2, "0")}</span>
              <span>{chapter.title}</span>
            </button>
          ))}
        </div>
        <div
          className="tb-section-theme-handoff__content"
          key={active.id}
          aria-live="polite"
        >
          <h2>{active.title}</h2>
          <p>{active.summary}</p>
        </div>
      </div>
    </section>
  );
}

export default SectionThemeHandoff;

.tb-section-theme-handoff {
  container-type: inline-size;
  min-height: inherit;
  color: var(--tb-theme-fg);
  background: var(--tb-theme-bg);
}

.tb-section-theme-handoff__layout {
  display: grid;
  grid-template-columns: minmax(220px, 0.65fr) minmax(0, 1.5fr);
  gap: clamp(38px, 8cqi, 110px);
  align-items: stretch;
  min-height: inherit;
  padding: clamp(26px, 6cqi, 78px);
}

.tb-section-theme-handoff__nav {
  display: grid;
  align-content: end;
}

.tb-section-theme-handoff__nav button {
  display: grid;
  grid-template-columns: 2.4rem minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  min-height: 52px;
  padding: 8px 0;
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, currentColor, transparent 56%);
  border-radius: 0;
  color: inherit;
  background: transparent;
  font: 580 0.86rem / 1.25 system-ui, sans-serif;
  text-align: left;
  cursor: pointer;
}

.tb-section-theme-handoff__nav button[aria-pressed="true"] {
  border-bottom-color: var(--tb-theme-accent);
  color: var(--tb-theme-accent);
  font-weight: 720;
}

.tb-section-theme-handoff__nav button:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 4px;
}

.tb-section-theme-handoff__content {
  align-self: center;
  animation: tb-section-theme-content-in 180ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.tb-section-theme-handoff__content h2 {
  max-width: 12ch;
  margin: 0;
  font: 660 clamp(2.7rem, 9cqi, 7rem) / 0.92 system-ui, sans-serif;
  letter-spacing: -0.065em;
}

.tb-section-theme-handoff__content p {
  max-width: 42ch;
  margin: clamp(22px, 4cqi, 38px) 0 0;
  font: 500 clamp(1rem, 2.1cqi, 1.22rem) / 1.5 system-ui, sans-serif;
}

@keyframes tb-section-theme-content-in {
  from { opacity: 0; transform: translateX(16px); }
}

@container (max-width: 620px) {
  .tb-section-theme-handoff__layout {
    grid-template-columns: 1fr;
    gap: 46px;
  }

  .tb-section-theme-handoff__nav {
    align-content: start;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tb-section-theme-handoff__content {
    animation: none;
  }
}

@media (forced-colors: active) {
  .tb-section-theme-handoff {
    color: CanvasText;
    background: Canvas;
  }

  .tb-section-theme-handoff__nav button[aria-pressed="true"] {
    color: Highlight;
  }
}
